FWSHIFT_EOF
if [ "${DRY_RUN:-0}" = 1 ]; then echo "DRY_RUN: the bodies are in $OUT"; exit 0; fi
: "${MERAKI_API_KEY:?set MERAKI_API_KEY}"
: "${NETWORK_ID:?set NETWORK_ID}"
MERAKI_BASE="${MERAKI_BASE:-https://api.meraki.com/api/v1}"
api GET "/networks/$NETWORK_ID/appliance/firewall/l3FirewallRules" > "$OUT/before-l3FirewallRules.json"
api PUT "/networks/$NETWORK_ID/appliance/firewall/l3FirewallRules" "$OUT/l3FirewallRules.json" > "$OUT/after-l3FirewallRules.json"
sleep 0.2
echo "done; the tables as they were are in $OUT/before-*.json"
# Not written:
#   ADMIN-SSH (port2): the source of the rule is in zone port2, and the MX names no zone: give the networks behind port2 with --zone-network
#   ADMIN-SSH (port1): the source of the rule is in zone port1, and the MX names no zone: give the networks behind port1 with --zone-network
#   WEB-IN: not converted: action Dst NAT: how the API spells its target list is not known, so the translation is not read
#   UPDATES: 'Updates (IPv4)' holds members only its platform knows
#   GRE-LAB: an ICMP type, or a protocol other than TCP, UDP, ICMP and ICMPv6: the MX has no field for it
#   TO-LAB: not converted: action Cascade: the rules of the rule list it hands traffic to are not read, and they decide that traffic
#   ODD: schedule '{"type": "recurring", "name": "Work-Hours"}' is not converted; the rule would apply at all times; schedule {"type": "recurring", "name": "Work-Hours"} is not converted
